INSERT INTO bible.author (author_id, display_name, also_known_as, honorifics, author_kind, year_of_birth, year_of_death, tradition, denomination, vocation, affiliations, nationality, summary_of_life, summary_source, wikidata_id, created_at) VALUES ('lockridge-shadrach-meshach', 'Shadrach Meshach Lockridge', 'S. M. Lockridge | Dr. S. M. Lockridge', 'Rev. Dr.', 'Person', '1913', '2000', 'Baptist', NULL, 'Pastor | Preacher', 'Calvary Baptist Church, San Diego', 'United States', 'American Baptist pastor and preacher, long-time pastor of Calvary Baptist Church in San Diego, best known for the sermon passage That''s My King.', 'Curated from model knowledge; dates match the transcript''s byline. Verify before citing.', NULL, '2026-10-30 02:10:53.173939+00') ON CONFLICT DO NOTHING;
INSERT INTO bible.author (author_id, display_name, also_known_as, honorifics, author_kind, year_of_birth, year_of_death, tradition, denomination, vocation, affiliations, nationality, summary_of_life, summary_source, wikidata_id, created_at) VALUES ('spurgeon-charles-haddon', 'Charles Haddon Spurgeon', 'C. H. Spurgeon | C.H. Spurgeon | Charles Spurgeon | The Prince of Preachers', 'Rev.', 'Person', '1834', '1892', 'Baptist', 'Particular Baptist (Calvinistic Baptist; held to the 1689 London Baptist Confession)', 'Pastor | Preacher | Author', 'New Park Street Chapel and the Metropolitan Tabernacle, London (pastor from 1854); the Pastors’ College', 'United Kingdom', 'English Particular Baptist preacher, born at Kelvedon, Essex on 19 June 1834; pastor of the New Park Street congregation, later the Metropolitan Tabernacle in London, for nearly four decades; died at Menton, France on 31 January 1892. His weekly published sermons fill the New Park Street and Metropolitan Tabernacle Pulpit.', 'Wikipedia (Charles Spurgeon); Dictionary of National Biography (1885-1900); Wikidata Q278825. Checked 2026-10-30.', 'Q278825', '2026-10-30 02:56:26.675611+00') ON CONFLICT DO NOTHING;
INSERT INTO bible.author (author_id, display_name, also_known_as, honorifics, author_kind, year_of_birth, year_of_death, tradition, denomination, vocation, affiliations, nationality, summary_of_life, summary_source, wikidata_id, created_at) VALUES ('duncan-j-ligon-iii', 'J. Ligon Duncan III', 'Ligon Duncan | Jennings Ligon Duncan III | Dr. J. Ligon Duncan III', 'Dr.', 'Person', '1960', NULL, 'Presbyterian', 'Presbyterian Church in America', 'Pastor | Theologian | Seminary chancellor', 'First Presbyterian Church, Jackson, Mississippi (senior minister 1996-2013); Reformed Theological Seminary (faculty; chancellor and CEO from 2013)', 'United States', 'American Presbyterian minister and theologian, born in Greenville, South Carolina on 29 November 1960; educated at Furman, Covenant Theological Seminary and the University of Edinburgh (PhD); senior minister of First Presbyterian Church, Jackson from 1996 to 2013, then chancellor and CEO of Reformed Theological Seminary.', 'Reformed Theological Seminary biography (rts.edu); Wikipedia (Ligon Duncan); Wikidata Q6546745. Sources differ on whether his FPC tenure ended in 2013 or January 2014. Checked 2026-10-30.', 'Q6546745', '2026-10-30 02:57:28.76534+00') ON CONFLICT DO NOTHING;
INSERT INTO bible.author (author_id, display_name, also_known_as, honorifics, author_kind, year_of_birth, year_of_death, tradition, denomination, vocation, affiliations, nationality, summary_of_life, summary_source, wikidata_id, created_at) VALUES ('ryle-john-charles', 'John Charles Ryle', 'J. C. Ryle | J.C. Ryle | Bishop Ryle', 'Rt. Rev.', 'Person', '1816', '1900', 'Anglican', 'Church of England (evangelical)', 'Bishop | Pastor | Author', 'Rector of Helmingham and vicar of Stradbroke, Suffolk; first Bishop of Liverpool (1880-1900)', 'United Kingdom', 'English evangelical Anglican, born at Macclesfield on 10 May 1816; educated at Eton and Christ Church, Oxford; a country pastor in Suffolk for nearly four decades, then the first Bishop of Liverpool from 1880; died in Lowestoft on 10 June 1900. Author of Expository Thoughts on the Gospels (1856-1869) and Holiness.', 'Wikipedia (J. C. Ryle); CCEL author page; Wikidata Q1076075. Suffolk parishes from standard biographies. Checked 2026-10-30.', 'Q1076075', '2026-10-30 02:57:28.76534+00') ON CONFLICT DO NOTHING;
INSERT INTO bible.author (author_id, display_name, also_known_as, honorifics, author_kind, year_of_birth, year_of_death, tradition, denomination, vocation, affiliations, nationality, summary_of_life, summary_source, wikidata_id, created_at) VALUES ('seccombe-david', 'David Seccombe', 'David Peter Seccombe | Dr David Seccombe', 'Dr.', 'Person', NULL, NULL, 'Anglican', NULL, 'New Testament scholar | Theological college principal', 'George Whitefield College, Cape Town (principal 1993-2012; research fellow); North-West University, Potchefstroom (affiliate professor of New Testament)', NULL, 'New Testament scholar (PhD, Cambridge) who succeeded Broughton Knox as principal of George Whitefield College, the evangelical Anglican college in Cape Town, from 1993 to 2012; author on Luke-Acts and the parables.', 'George Whitefield College history (gwc.ac.za); Sydney Anglicans news; Anglican Church League. No birth year or nationality found; no Wikidata item. Checked 2026-10-30.', NULL, '2026-10-30 03:12:35.170369+00') ON CONFLICT DO NOTHING;
INSERT INTO bible.author (author_id, display_name, also_known_as, honorifics, author_kind, year_of_birth, year_of_death, tradition, denomination, vocation, affiliations, nationality, summary_of_life, summary_source, wikidata_id, created_at) VALUES ('burke-trevor-j', 'Trevor J. Burke', 'Trevor Burke', 'Dr.', 'Person', '1956', NULL, NULL, NULL, 'New Testament scholar | Professor of Bible', 'Moody Bible Institute, Chicago (professor of Bible); earlier seminary posts in Nigeria, Wales and Fiji (Pacific Theological College, Suva)', 'United Kingdom', 'New Testament scholar born in Belfast in 1956; PhD, University of Glasgow; professor of Bible at Moody Bible Institute; author of Adopted into God’s Family (NSBT, 2006) and works on family language in Paul.', 'InterVarsity Press author page; nightlight.org interview (2007); Wikidata Q93241839 (born 27 September 1956, Belfast; employer Moody Bible Institute). Checked 2026-10-30.', 'Q93241839', '2026-10-30 03:12:35.272922+00') ON CONFLICT DO NOTHING;
INSERT INTO bible.author (author_id, display_name, also_known_as, honorifics, author_kind, year_of_birth, year_of_death, tradition, denomination, vocation, affiliations, nationality, summary_of_life, summary_source, wikidata_id, created_at) VALUES ('arnot-william', 'William Arnot', 'Rev. William Arnot | W. Arnot', 'Rev.', 'Person', '1808', '1875', 'Presbyterian', 'Church of Scotland; Free Church of Scotland from the Disruption of 1843', 'Pastor | Author | Editor', 'St Peter''s Church, Glasgow (ordained 1838; Free Church from 1843); Free High Church, Edinburgh (1863-1875); editor of The Family Treasury (from 1871)', 'United Kingdom', 'Scottish Presbyterian minister, born in the parish of Forgandenny, Perthshire on 6 November 1808; educated at Glasgow University; ordained to St Peter''s Church, Glasgow in 1838 and went out with most of his congregation into the Free Church of Scotland at the Disruption of 1843; minister of the Free High Church, Edinburgh from 1863; declined honorary doctorates from Glasgow and New York; died in Edinburgh on 3 June 1875. Author of Laws from Heaven for Life on Earth and The Parables of Our Lord.', 'Wikipedia (William Arnot (minister)); Wikidata Q8004560 (born 6 Nov 1808; died 3 Jun 1875, Edinburgh). Checked 2026-10-30.', 'Q8004560', '2026-10-30 03:31:18.131126+00') ON CONFLICT DO NOTHING;
INSERT INTO bible.author (author_id, display_name, also_known_as, honorifics, author_kind, year_of_birth, year_of_death, tradition, denomination, vocation, affiliations, nationality, summary_of_life, summary_source, wikidata_id, created_at) VALUES ('calvin-john', 'John Calvin', 'Jean Calvin | Jehan Cauvin | Ioannes Calvinus | Calvin', NULL, 'Person', '1509', '1564', 'Reformed', 'Reformed Church of Geneva', 'Reformer | Pastor | Theologian | Commentator', 'Pastor and lecturer in Geneva (1536-1538, 1541-1564); minister to the French refugee congregation in Strasbourg (1538-1541); founder of the Genevan Academy (1559)', 'France', 'French Protestant Reformer, born at Noyon, Picardy on 10 July 1509; trained in law at Orleans and Bourges; first published the Institutes of the Christian Religion in 1536; pastor and teacher in Geneva from 1536, exiled 1538-1541 and ministering in Strasbourg, then in Geneva until his death there on 27 May 1564. His Latin commentaries cover most of the Bible; the Harmony of Matthew, Mark and Luke appeared in 1555.', 'Wikipedia (John Calvin); Wikidata Q37577 (born 10 Jul 1509, Noyon; died 27 May 1564, Geneva); the 1555 date from his own Epistle Dedicatory in this edition (Geneva, 1 August 1555). Checked 2026-10-30.', 'Q37577', '2026-10-30 03:42:29.782828+00') ON CONFLICT DO NOTHING;
INSERT INTO bible.author (author_id, display_name, also_known_as, honorifics, author_kind, year_of_birth, year_of_death, tradition, denomination, vocation, affiliations, nationality, summary_of_life, summary_source, wikidata_id, created_at) VALUES ('pringle-william', 'William Pringle', 'Rev. William Pringle | W. P.', 'Rev.', 'Person', '1796', '1873', 'Presbyterian', NULL, 'Pastor | Translator', 'Minister at Auchterarder, Perthshire; translator for the Calvin Translation Society, Edinburgh (1840s-1850s)', 'United Kingdom', 'Scottish Presbyterian minister and translator, born at Tranent, East Lothian on 19 July 1796; minister at Auchterarder, Perthshire, where he signed his translator''s prefaces; translated from the Latin Witsius on the Lord''s Prayer (1839) and, for the Calvin Translation Society, Calvin''s Harmony of the Evangelists (1845-46), John (1847), Isaiah (1850-53) and the Pastoral Epistles (1856); died at Auchterarder on 16 February 1873.', 'Wikidata Q101052346 (born 19 Jul 1796, Tranent; died 16 Feb 1873, Auchterarder); Wikisource Author:William Pringle (translations); translator''s preface signed W. P., Auchterarder, 4 January 1845. His Presbyterian body (Secession or Established) not confirmed. Checked 2026-10-30.', 'Q101052346', '2026-10-30 03:42:29.782828+00') ON CONFLICT DO NOTHING;
