INSERT INTO bible.work (work_id, display_name, also_known_as, work_type, date_label, year, occasion, language, work_summary, wikidata_id, created_at) VALUES ('spurgeon-0308-the-parable-of-the-sower', 'The Parable of the Sower', 'Sermon No. 308', 'Sermon', 'Sunday morning, April 15, 1860', '1860', 'Preached at Exeter Hall, Strand, London', 'en', 'Spurgeon on the four kinds of hearers in the parable of the sower: the wayside, the rock, the thorns and the good ground.', NULL, '2026-10-30 02:56:26.675611+00') ON CONFLICT DO NOTHING;
