INSERT INTO bible.work (work_id, display_name, also_known_as, work_type, date_label, year, occasion, language, work_summary, wikidata_id, created_at) VALUES ('seccombe-incongruity-in-the-gospel-parables', 'Incongruity in the Gospel Parables', NULL, 'Article', '2011', '2011', 'Published in Tyndale Bulletin 62.2 (2011), pp. 161-172', 'en', 'Argues that Jesus deliberately used incongruity and the bizarre in his parables, re-examines the parable of the leaven, and applies the result to the parable of the ten minas.', NULL, '2026-10-30 03:12:35.170369+00') ON CONFLICT DO NOTHING;
INSERT INTO bible.work (work_id, display_name, also_known_as, work_type, date_label, year, occasion, language, work_summary, wikidata_id, created_at) VALUES ('burke-parable-of-the-prodigal-father', 'The Parable of the Prodigal Father', 'The Parable of the Prodigal Father: An Interpretative Key to the Third Gospel', 'Article', '2013', '2013', 'Published in Tyndale Bulletin 64.2 (2013), pp. 217-238', 'en', 'Argues that Luke 15:11-32 is best read from the father’s perspective as the parable of the prodigal father, whose extravagant generosity fits Luke’s wider theme of prodigality in the kingdom of God.', NULL, '2026-10-30 03:12:35.272922+00') ON CONFLICT DO NOTHING;
INSERT INTO bible.work (work_id, display_name, also_known_as, work_type, date_label, year, occasion, language, work_summary, wikidata_id, created_at) VALUES ('ryle-expository-thoughts-on-the-gospels', 'Expository Thoughts on the Gospels', NULL, 'CommentarySeries', '1856-1869 (seven volumes)', NULL, NULL, 'en', 'Ryle’s devotional, passage-by-passage commentary on the four Gospels, written for family and private reading.', NULL, '2026-10-30 03:21:22.896435+00') ON CONFLICT DO NOTHING;
INSERT INTO bible.work (work_id, display_name, also_known_as, work_type, date_label, year, occasion, language, work_summary, wikidata_id, created_at) VALUES ('ryle-expository-thoughts-on-matthew', 'Expository Thoughts on Matthew', NULL, 'Commentary', '1856', '1856', NULL, 'en', 'Ryle’s exposition of Matthew in 96 passages, each followed by practical and devotional lessons.', NULL, '2026-10-30 03:21:22.896435+00') ON CONFLICT DO NOTHING;
INSERT INTO bible.work (work_id, display_name, also_known_as, work_type, date_label, year, occasion, language, work_summary, wikidata_id, created_at) VALUES ('arnot-parables-of-our-lord', 'The Parables of Our Lord', NULL, 'Commentary', '1864/65; this edition 1874', NULL, NULL, 'en', 'Arnot''s expositions of thirty parables of Jesus from Matthew, Mark and Luke, with an introduction on analogy and the interpretation of parables, grouped as the book groups them (Matthew 13, Matthew 21-22, Matthew 25, Luke 15).', NULL, '2026-10-30 03:31:18.131126+00') ON CONFLICT DO NOTHING;
INSERT INTO bible.work (work_id, display_name, also_known_as, work_type, date_label, year, occasion, language, work_summary, wikidata_id, created_at) VALUES ('calvin-harmony-of-the-evangelists', 'Commentary on a Harmony of the Evangelists', 'Harmonia ex tribus Evangelistis composita | Harmony of the Gospels | Commentary on Matthew, Mark, and Luke', 'Commentary', '1555 (Latin)', '1555', NULL, 'la', 'Calvin''s commentary on Matthew, Mark and Luke arranged as one harmonised narrative, each section printing the parallel Gospel texts side by side before the exposition.', NULL, '2026-10-30 03:42:29.782828+00') ON CONFLICT DO NOTHING;
